<?php require_once __DIR__.'/../_bootstrap.php';admin();$d=body();required($d,['user_id','new_password']);if(strlen($d['new_password'])<6)fail('Password must be at least 6 characters.');$check=db()->prepare('SELECT id FROM users WHERE id=?');$check->execute([$d['user_id']]);if(!$check->fetch())fail('User not found.',404);$s=db()->prepare('UPDATE users SET password=? WHERE id=?');$s->execute([password_hash($d['new_password'],PASSWORD_DEFAULT),$d['user_id']]);out(['success'=>true,'message'=>'Password reset successfully.']);
